#include <iostream>
#include <sstream>
#include <string>

void probar(const std::string& texto) {
    std::istringstream entrada{texto};
    std::string linea;
    int cantidad = 0;
    int vacias = 0;

    while (std::getline(entrada, linea)) {
        ++cantidad;

        if (linea.empty()) {
            ++vacias;
        }

        std::cout << cantidad << ":<" << linea << ">\n";
    }

    std::cout << "Lineas: " << cantidad << "\nVacias: " << vacias;
    std::cout << "\n";
}

int main() {
    probar("Patio norte\n\n  Muelle\n");
    probar("");
    probar("\n");
    probar("  ");
    probar("A\n");
    probar("A\n\n");

    return 0;
}

